import json, hashlib, sys

def sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(1 << 20), b''):
            h.update(chunk)
    return h.hexdigest()

fz = json.load(open('workspace/tmp/pr197-f5-prreview-20261002/freeze.json'))
mismatch = []
missing = []
ok = 0
for section in ('files', 'validation', 'snapshot'):
    for path, expect in fz[section].items():
        try:
            actual = sha256(path)
        except FileNotFoundError:
            missing.append((section, path))
            continue
        if actual != expect:
            mismatch.append((section, path, expect, actual))
        else:
            ok += 1

for key, path_key in (('samebytes_proof', 'samebytes_proof'), ('selected_exact_PR_diff', 'selected_exact_PR_diff')):
    expect = fz[key + '_sha256'] if key + '_sha256' in fz else None
    path = fz[path_key]
    actual = sha256(path)
    if actual != expect:
        mismatch.append((key, path, expect, actual))
    else:
        ok += 1

print(f"verified_ok={ok}")
print(f"missing={len(missing)}")
for s, p in missing:
    print(f"MISSING {s}: {p}")
print(f"mismatch={len(mismatch)}")
for s, p, e, a in mismatch:
    print(f"MISMATCH {s}: {p} expect={e} actual={a}")
